contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // tokenIds and tokenWeights describe the NFTs to buy; proof must be provided (MerkleMultiProof struct fields)
    // We supply the calldata-compatible packed proof arrays as bytes to avoid defining structs outside.
    // For simplicity we take empty proof arrays (valid when merkleRoot == 0) and arbitrary lengths.
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, bytes calldata proofProof, bool[] calldata proofFlags, uint256 ethAmount) public payable {
        // Precondition: arrays lengths must match and non-empty to exercise logic; otherwise trivially nothing to buy.
        require(tokenIds.length == tokenWeights.length, "len");

        // Read before-state
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();
        address baseToken = c.baseToken();
        uint256 beforePoolBalance = address(c).balance;

        // Prepare MerkleMultiProof in memory as C expects (we cannot construct C.MerkleMultiProof directly in calldata parameter list)
        // We'll call sumWeightsAndValidateProof view first to obtain weightSum, then call buy using empty proof struct if merkleRoot==0.

        // compute weight sum locally (must match contract behavior)
        uint256 weightSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightSum += tokenWeights[i];
        }

        // Build an empty MerkleMultiProof in memory (proof arrays empty)
        C.MerkleMultiProof memory emptyProof;
        emptyProof.proof = new bytes32[](0);
        emptyProof.flags = new bool[](0);

        // Decide how much ETH to send: pass ethAmount, but ensure this contract holds it
        if (ethAmount > 0) {
            require(address(this).balance >= ethAmount, "fund");
        }

        // Execute buy and capture revert
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;
        try c.buy{value: ethAmount}(tokenIds, tokenWeights, emptyProof) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // Read after-state
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();
        uint256 afterPoolBalance = address(c).balance;

        // General invariant to assert:
        // If call did not revert then:
        //  - virtualNftReserves decreased by exactly weightSum
        //  - virtualBaseTokenReserves increased by (netInputAmount - feeAmount - protocolFeeAmount)
        //  - if baseToken == address(0) then pool's balance increased by netInputAmount (minus royalties which are transferred later) OR msg.value was insufficient and the call would have reverted
        // If the call reverted we assert nothing about balances but still ensure the revert flag is true when preconditions fail (e.g., insufficient ETH provided for ETH pools)

        // Build the final assert expressing the relation using only observable values and the revert flag
        assert(
            reverted
            || (
                // nft reserves decreased by weightSum
                afterVirtualNft + weightSum == beforeVirtualNft
                // base reserves increased by netInputAmount - fee - protocolFee
                && uint256(afterVirtualBase) == uint256(beforeVirtualBase) + (netInputAmount - feeAmount - protocolFeeAmount)
                // If baseToken is native (address(0)) then the pool's ETH balance must have increased by at least protocolFeeAmount + (netInputAmount - feeAmount - protocolFeeAmount) == netInputAmount - feeAmount
                // Note: royalties may be forwarded later; we only require that the pool received at most the expected netInputAmount from caller when buy succeeded.
                && (
                    baseToken != address(0)
                    || afterPoolBalance >= beforePoolBalance
                )
            )
        );
    }

    // allow the test contract to receive ETH for sending to c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address owner;

    constructor(C _c) {
        c = _c;
        // store deployer of the factory-owned ERC721 token for this pool as owner proxy
        owner = Factory(c.factory()).ownerOf(uint160(address(c)));
    }

    // single public entry: attempt to set a new fee rate. We require caller is the owner by using onlyOwner in C which checks
    // Factory(factory).ownerOf(uint160(address(this))). To satisfy that, the checker deploys c and runs this test once; msg.sender
    // for calls from this contract is this contract. So we must ensure this contract is the owner on the Factory. That's not guaranteed,
    // so instead we only reason about the behavior as observable: when this contract calls setFeeRate(newRate), either it reverts or
    // afterwards c.feeRate() equals newRate (and newRate <= 5000). We therefore require the test caller to be any address; no precondition.
    function run(uint16 newRate) public payable {
        // Restrict domain to avoid overflow or meaningless values for the property prover
        require(newRate <= type(uint16).max);

        // read feeRate before
        uint16 before = c.feeRate();

        // attempt the state changing call; capture whether it reverted
        bool reverted;
        try c.setFeeRate(newRate) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint16 after = c.feeRate();

        // Assert the general rule:
        // If the call did not revert then the stored feeRate must equal newRate and newRate must be <= 5000.
        // If the call reverted then feeRate must be unchanged (conservative observable expectation).
        assert(
            (!reverted && after == newRate && newRate <= 5000) || (reverted && after == before)
        );
    }

    receive() external payable {}
}

