contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that will be used as the property-based test
    // params:
    // - tokenIds and tokenWeights are the arrays passed to buy
    // - proof is the MerkleMultiProof packed as (bytes32[] proof, bool[] flags) via calldata-like memory args
    // - payAmount: Ether forwarded to c when calling buy (used only if baseToken == address(0))
    function run(uint256[] memory tokenIds, uint256[] memory tokenWeights, bytes32[] memory proofProof, bool[] memory proofFlags, uint256 payAmount) public payable {
        require(tokenIds.length == tokenWeights.length, "len");

        // read pre-state via public getters
        uint128 beforeVirtualNftReserves = c.virtualNftReserves();
        uint128 beforeVirtualBaseTokenReserves = c.virtualBaseTokenReserves();

        // compute the sum of tokenWeights locally (this mirrors internal behavior but is allowed)
        uint256 weightSum = 0;
        for (uint256 i = 0; i < tokenWeights.length; i++) {
            weightSum += tokenWeights[i];
        }

        // Build MerkleMultiProof struct in memory to pass to buy
        C.MerkleMultiProof memory proof;
        proof.proof = proofProof;
        proof.flags = proofFlags;

        // We must ensure we have Ether to forward if payAmount > 0
        if (payAmount > 0) {
            require(address(this).balance >= payAmount, "no funds");
        }

        // Attempt the buy call and capture whether it reverted and the returned values if any
        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // Top-level state-changing call as required. Use try/catch to detect revert.
        try c.buy{value: payAmount}(tokenIds, tokenWeights, proof) returns (uint256 _netInput, uint256 _fee, uint256 _protocol) {
            reverted = false;
            netInputAmount = _netInput;
            feeAmount = _fee;
            protocolFeeAmount = _protocol;
        } catch {
            reverted = true;
        }

        // read post-state
        uint128 afterVirtualNftReserves = c.virtualNftReserves();
        uint128 afterVirtualBaseTokenReserves = c.virtualBaseTokenReserves();

        // If the call reverted, we assert nothing about balances except that state didn't change for the two tracked variables
        // (buy must be atomic). If it succeeded, enforce the invariant on virtual reserves.
        assert(
            reverted
                ? (afterVirtualNftReserves == beforeVirtualNftReserves && afterVirtualBaseTokenReserves == beforeVirtualBaseTokenReserves)
                : (
                    // when successful, virtualNftReserves must decrease by weightSum
                    // and virtualBaseTokenReserves must increase by (netInputAmount - feeAmount - protocolFeeAmount)
                    // Use explicit conversions to avoid underflow in the assert expression.
                    uint256(beforeVirtualNftReserves) >= weightSum &&
                    uint256(beforeVirtualNftReserves) - weightSum == uint256(afterVirtualNftReserves) &&
                    uint256(afterVirtualBaseTokenReserves) == uint256(beforeVirtualBaseTokenReserves) + (netInputAmount - feeAmount - protocolFeeAmount)
                  )
        );
    }

    // receive to allow funding this contract for payAmount
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: deposit tokenIds and baseTokenAmount (for ether or ERC20)
    function run(uint256[] memory tokenIds, uint256 baseTokenAmount) public payable {
        // keep test small: limit array length to avoid heavy proofs
        require(tokenIds.length <= 5, "len");

        // Read observable pre-state
        uint256 beforeNftBalance = ERC721(c.nft()).balanceOf(address(c));
        address base = c.baseToken();
        uint256 beforeBaseBalance;
        if (base == address(0)) {
            beforeBaseBalance = address(c).balance;
            // ensure this test contract has enough ETH to forward if needed
            if (baseTokenAmount > 0) require(address(this).balance >= baseTokenAmount, "no-eth");
        } else {
            beforeBaseBalance = ERC20(base).balanceOf(address(c));
        }

        // Perform the state-changing call at top level and capture revert
        bool reverted;
        try c.deposit{value: base == address(0) ? baseTokenAmount : 0}(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable post-state
        uint256 afterNftBalance = ERC721(c.nft()).balanceOf(address(c));
        uint256 afterBaseBalance;
        if (base == address(0)) {
            afterBaseBalance = address(c).balance;
        } else {
            afterBaseBalance = ERC20(base).balanceOf(address(c));
        }

        // Assert atomicity: if reverted then balances unchanged; otherwise nft balance increased by tokenIds.length and base balance increased by baseTokenAmount
        assert(
            reverted
                ? (afterNftBalance == beforeNftBalance && afterBaseBalance == beforeBaseBalance)
                : (
                    afterNftBalance == beforeNftBalance + tokenIds.length &&
                    afterBaseBalance == beforeBaseBalance + baseTokenAmount
                  )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: attempt withdraw of given nft contract, tokenIds, token address, and tokenAmount
    function run(address _nft, uint256[] calldata tokenIds, address token, uint256 tokenAmount) public payable {
        // keep arrays small for solver
        require(tokenIds.length <= 4, "len");

        // Observe pre-state via public interfaces
        uint256 beforeNftBalance = ERC721(c.nft()).balanceOf(address(c));
        address base = c.baseToken();
        uint256 beforeBaseBalance;
        if (base == address(0)) {
            beforeBaseBalance = address(c).balance;
            // If the call will send ETH back to owner on success, no need to fund this contract.
        } else {
            beforeBaseBalance = ERC20(base).balanceOf(address(c));
        }

        // Record ownership of each tokenId on _nft before
        bool[] memory beforeOwned = new bool[](tokenIds.length);
        for (uint256 i = 0; i < tokenIds.length; i++) {
            // try/catch not allowed for external view so use low-level staticcall via the public ownerOf
            // but ownerOf is a public function; call it and catch via try/catch is allowed only for external calls that may revert
            try ERC721(_nft).ownerOf(tokenIds[i]) returns (address owner) {
                beforeOwned[i] = (owner == address(c));
            } catch {
                beforeOwned[i] = false;
            }
        }

        // Perform the state-changing call at top level and capture whether it reverted
        bool reverted;
        try c.withdraw(_nft, tokenIds, token, tokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 afterNftBalance = ERC721(c.nft()).balanceOf(address(c));
        uint256 afterBaseBalance;
        if (base == address(0)) {
            afterBaseBalance = address(c).balance;
        } else {
            afterBaseBalance = ERC20(base).balanceOf(address(c));
        }

        // Check ownership after for each tokenId
        bool[] memory afterOwned = new bool[](tokenIds.length);
        for (uint256 i = 0; i < tokenIds.length; i++) {
            try ERC721(_nft).ownerOf(tokenIds[i]) returns (address owner) {
                afterOwned[i] = (owner == address(c));
            } catch {
                afterOwned[i] = false;
            }
        }

        // General invariant: if reverted, nothing observable changed; otherwise, each token that was owned by the pool before must no longer be owned by the pool afterwards (transferred out), and nft balance decreased by number of such tokens, and base-token balance decreased by tokenAmount (owner received it)
        uint256 ownedCountBefore = 0;
        uint256 ownedCountAfter = 0;
        for (uint256 i = 0; i < tokenIds.length; i++) {
            if (beforeOwned[i]) ownedCountBefore++;
            if (afterOwned[i]) ownedCountAfter++;
        }

        assert(
            reverted
                ? (afterNftBalance == beforeNftBalance && afterBaseBalance == beforeBaseBalance && ownedCountAfter == ownedCountBefore)
                : (
                    // success: pool's nft balance decreased by exactly number of tokens it previously owned among the provided list
                    afterNftBalance == beforeNftBalance - ownedCountBefore
                    // and pool's base-token balance decreased by tokenAmount
                    && afterBaseBalance == beforeBaseBalance - tokenAmount
                    // and none of the tokens that pool owned remain owned by the pool
                    && ownedCountAfter == 0
                  )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: attempt withdraw of given nft contract, tokenIds, token address, and tokenAmount
    function run(address _nft, uint256[] calldata tokenIds, address token, uint256 tokenAmount) public payable {
        // keep arrays small to help solver
        require(tokenIds.length <= 4, "len");

        // Observe pre-state via public interfaces (only allowed public reads)
        uint256 beforeNftBalance = ERC721(c.nft()).balanceOf(address(c));
        address base = c.baseToken();
        uint256 beforeBaseBalance;
        if (base == address(0)) {
            beforeBaseBalance = address(c).balance;
        } else {
            beforeBaseBalance = ERC20(base).balanceOf(address(c));
        }

        // Record ownership of each tokenId on the supplied _nft before
        bool[] memory beforeOwned = new bool[](tokenIds.length);
        for (uint256 i = 0; i < tokenIds.length; i++) {
            try ERC721(_nft).ownerOf(tokenIds[i]) returns (address owner) {
                beforeOwned[i] = (owner == address(c));
            } catch {
                beforeOwned[i] = false;
            }
        }

        // Perform the state-changing call at top level and capture whether it reverted
        bool reverted;
        try c.withdraw(_nft, tokenIds, token, tokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 afterNftBalance = ERC721(c.nft()).balanceOf(address(c));
        uint256 afterBaseBalance;
        if (base == address(0)) {
            afterBaseBalance = address(c).balance;
        } else {
            afterBaseBalance = ERC20(base).balanceOf(address(c));
        }

        // Record ownership after for each tokenId
        bool[] memory afterOwned = new bool[](tokenIds.length);
        for (uint256 i = 0; i < tokenIds.length; i++) {
            try ERC721(_nft).ownerOf(tokenIds[i]) returns (address owner) {
                afterOwned[i] = (owner == address(c));
            } catch {
                afterOwned[i] = false;
            }
        }

        // Count how many of the provided tokenIds the pool owned before and after
        uint256 ownedCountBefore = 0;
        uint256 ownedCountAfter = 0;
        for (uint256 i = 0; i < tokenIds.length; i++) {
            if (beforeOwned[i]) ownedCountBefore++;
            if (afterOwned[i]) ownedCountAfter++;
        }

        // Assert general property: either nothing observable changed on revert, or on success
        // the pool's NFT balance decreased by exactly ownedCountBefore, none of those previously-owned tokens remain owned by the pool,
        // and the pool's base-token/ETH balance decreased by exactly tokenAmount.
        assert(
            reverted
                ? (
                    afterNftBalance == beforeNftBalance
                    && afterBaseBalance == beforeBaseBalance
                    && ownedCountAfter == ownedCountBefore
                  )
                : (
                    // success: nft balance decreased by number of tokens it previously owned among the list
                    afterNftBalance == beforeNftBalance - ownedCountBefore
                    // and none of those previously-owned tokens remain owned by the pool
                    && ownedCountAfter == 0
                    // and base token balance decreased by exactly tokenAmount
                    && afterBaseBalance + tokenAmount == beforeBaseBalance
                  )
        );
    }

    receive() external payable {}
}
